{
  "source_id": "TEXT",
  "cast": [
    {
      "id": "P01",
      "name": "格雷戈尔·萨姆沙"
    },
    {
      "id": "P02",
      "name": "母亲"
    },
    {
      "id": "P03",
      "name": "父亲"
    },
    {
      "id": "P04",
      "name": "妹妹"
    }
  ],
  "locations": [
    {
      "id": "L01",
      "name": "格雷戈尔的房间与门外"
    }
  ],
  "scenes": [
    {
      "sceneId": "L01",
      "characters": [
        "P01",
        "P02",
        "P03",
        "P04"
      ],
      "flow": [
        {
          "action": "格雷戈尔在床中醒来，仰面躺着，褐色腹部分成弧形硬片。"
        },
        {
          "action": "被子从他隆起的腹部滑下，露出更多硬片。"
        },
        {
          "speaker": "P01",
          "line": "我出什么事了？",
          "mode": "inner"
        },
        {
          "action": "许多细弱的腿在他眼前无助地颤动。"
        },
        {
          "action": "他望向墙上金色镜框里的裘皮帽女士。"
        },
        {
          "action": "他望向桌上摊开的货品选样。"
        },
        {
          "action": "他望向阴沉窗户，雨滴打在铁皮窗檐上。"
        },
        {
          "action": "他用力向右侧翻身，却摇晃着转回仰卧。"
        },
        {
          "action": "他闭上眼。"
        },
        {
          "action": "他的腰侧传来钝痛，腿停止颤动。"
        },
        {
          "speaker": "P01",
          "line": "我选了个多么累人的职业啊！",
          "mode": "spoken"
        },
        {
          "speaker": "P01",
          "line": "让这一切都见鬼去吧！",
          "mode": "spoken"
        },
        {
          "action": "他抬头看见肚子上布满白色小点。"
        },
        {
          "action": "他缩回想碰的腿。"
        },
        {
          "action": "他滑回原来的地方。"
        },
        {
          "speaker": "P01",
          "line": "天哪，六点三刻了，火车要开了。",
          "mode": "inner"
        },
        {
          "action": "他看向柜子上的闹钟，指针接近六点三刻。"
        },
        {
          "speaker": "P01",
          "line": "下一班火车七点开，我得火速行动。",
          "mode": "spoken"
        },
        {
          "speaker": "P01",
          "line": "请病假会很尴尬，也显得可疑。",
          "mode": "spoken"
        },
        {
          "speaker": "P01",
          "line": "我工作五年还没生过一次病。",
          "mode": "spoken"
        },
        {
          "speaker": "P01",
          "line": "老板会带医生来，责怪我的父母。",
          "mode": "spoken"
        },
        {
          "action": "母亲在门边轻轻敲门，探身询问。"
        },
        {
          "speaker": "P02",
          "line": "格雷戈尔，六点三刻了，你不是还得赶火车吗？",
          "mode": "spoken"
        },
        {
          "speaker": "P01",
          "line": "是的，是的，谢谢，妈妈，我这就起床。",
          "mode": "spoken"
        },
        {
          "action": "母亲放心地踢踢踏踏走开。"
        },
        {
          "action": "父亲在侧面门用拳头轻敲。"
        },
        {
          "speaker": "P03",
          "line": "格雷戈尔！格雷戈尔！你怎么啦？",
          "mode": "spoken"
        },
        {
          "speaker": "P03",
          "line": "格雷戈尔！格雷戈尔！",
          "mode": "spoken"
        },
        {
          "action": "妹妹在另一侧门轻轻说话。"
        },
        {
          "speaker": "P04",
          "line": "格雷戈尔？你是不是不舒服？你需要什么吗？",
          "mode": "spoken"
        },
        {
          "speaker": "P01",
          "line": "我这就好了。",
          "mode": "spoken"
        },
        {
          "action": "父亲转身回去吃早餐。"
        },
        {
          "speaker": "P04",
          "line": "格雷戈尔，开开门，我求你了。",
          "mode": "spoken"
        },
        {
          "action": "格雷戈尔的手指轻轻抵住门锁。"
        },
        {
          "action": "妹妹在门外停下。"
        }
      ]
    }
  ]
}

